#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_bf16.h>
#include <mma.h>
constexpr int CIN = 3;
constexpr int COUT = 32;
constexpr int K = 3;
constexpr int TILE_OH = 8;
constexpr int TILE_OW = 16;
constexpr int TILE_IH = TILE_OH + 2;   // staged input tile rows (3x3 halo)
constexpr int TILE_IW = TILE_OW + 2;   // staged input tile cols (3x3 halo)
constexpr int TILE_IW_PAD = TILE_IW + 2;  // padded stride to reduce bank conflicts
constexpr int TILE_M = TILE_OH * TILE_OW;
constexpr int KTILE = 32;
constexpr int THREADS = 256;
constexpr int LDS = 36;  // multiple of 4 (required by WMMA float store), non-multiple of 32 (bank-conflict mitigation)
using namespace nvcuda;
// Tensor-core (WMMA) implicit-GEMM convolution:
//   GEMM M = output pixels (8x16 spatial tile = 128 per block)
//   GEMM N = output channels (32)
//   GEMM K = CIN*K*K = 27 (padded to 32)
// Each block has 8 warps; each warp computes a 16(pixels) x 32(channels)
// tile as a 1x2 grid of 16x16x16 bf16 MMA fragments.
__global__ void conv2d_3x3_cin3_cout32_bf16_kernel(
    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    const int N,
    const int H,
    const int W,
    const int Ho,
    const int Wo) {
  __shared__ __align__(32) __nv_bfloat16 sA[TILE_M][KTILE];
  __shared__ __align__(32) __nv_bfloat16 sB[KTILE][COUT];
  __shared__ __align__(32) __nv_bfloat16 sX[CIN][TILE_IH][TILE_IW_PAD];
  __shared__ __align__(32) float sOut[TILE_M / 32][32][LDS];
  const int tid = threadIdx.x;
  const int warp = tid >> 5;
  const int ow0 = blockIdx.x * TILE_OW;
  const int oh0 = blockIdx.y * TILE_OH;
  const int n = blockIdx.z;
  // Stage weights: sB[k][co] = w[co][k] (k = ci*9 + kh*3 + kw), zero-pad k >= 27.
  for (int idx = tid; idx < KTILE * COUT; idx += THREADS) {
    const int k = idx >> 5;
    const int co = idx & 31;
    sB[k][co] = (k < CIN * K * K)
                    ? w[co * (CIN * K * K) + k]
                    : __float2bfloat16(0.0f);
  }
  // Stage the raw input tile (3x3 halo included) into shared memory with
  // coalesced global loads: consecutive threads read consecutive columns
  // of x, replacing the previous scattered im2col global reads.
  for (int idx = tid; idx < CIN * TILE_IH * TILE_IW; idx += THREADS) {
    const int iw = idx % TILE_IW;
    const int r = (idx / TILE_IW) % TILE_IH;
    const int ci = idx / (TILE_IW * TILE_IH);
    const int ih = oh0 + r;
    const int jw = ow0 + iw;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (ih < H && jw < W) {
      v = x[((long long)(n * CIN + ci) * H + ih) * W + jw];
    }
    sX[ci][r][iw] = v;
  }
  __syncthreads();
  // Build the im2col operand sA[m][k] from the staged input tile
  // (shared-memory reads only), zero-padding k >= 27.
  for (int idx = tid; idx < TILE_M * KTILE; idx += THREADS) {
    const int m = idx >> 5;
    const int k = idx & 31;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (k < CIN * K * K) {
      const int ci = k / 9;
      const int r = k - ci * 9;
      const int kh = r / 3;
      const int kw = r - kh * 3;
      v = sX[ci][(m >> 4) + kh][(m & 15) + kw];
    }
    sA[m][k] = v;
  }
  __syncthreads();
  wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[2];
#pragma unroll
  for (int j = 0; j < 2; ++j) {
    wmma::fill_fragment(acc[j], 0.0f);
  }
  // 8 warps x 16 pixels = TILE_M = 128; each warp covers all 32
  // output channels as two 16-wide N-fragments.
  const int m0 = warp * 16;
#pragma unroll
  for (int ki = 0; ki < 2; ++ki) {
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> a;
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> b[2];
    wmma::load_matrix_sync(a, &sA[m0][ki * 16], KTILE);
    wmma::load_matrix_sync(b[0], &sB[ki * 16][0], COUT);
    wmma::load_matrix_sync(b[1], &sB[ki * 16][16], COUT);
    wmma::mma_sync(acc[0], a, b[0], acc[0]);
    wmma::mma_sync(acc[1], a, b[1], acc[1]);
  }
  // Pixels [16*warp, 16*warp+16) live in sOut group (warp>>1),
  // row offset (warp&1)*16, matching the epilogue indexing below.
  wmma::store_matrix_sync(&sOut[warp >> 1][(warp & 1) * 16][0], acc[0], LDS, wmma::mem_row_major);
  wmma::store_matrix_sync(&sOut[warp >> 1][(warp & 1) * 16][16], acc[1], LDS, wmma::mem_row_major);
  __syncthreads();
  // Write results back as bf16; consecutive threads cover consecutive pixels
  // (16 contiguous pixels per row) for coalesced stores.
  for (int idx = tid; idx < TILE_M * COUT; idx += THREADS) {
    const int co = idx >> 7;
    const int pix = idx & (TILE_M - 1);
    const int oh = oh0 + (pix >> 4);
    const int ow = ow0 + (pix & 15);
    if (oh < Ho && ow < Wo) {
      const float v = sOut[pix >> 5][pix & 31][co];
      y[((long long)(n * COUT + co) * Ho + oh) * Wo + ow] =
          __float2bfloat16_rn(v);
    }
  }
}
