      reinterpret_cast<const __nv_bfloat16*>(wc.data_ptr<at::BFloat16>()),
      reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>()),
      N, H, W, Ho, Wo);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
